[CmdletBinding()]
param([string]$Path = (Join-Path (Split-Path -Parent $PSScriptRoot) '.env'))
$ErrorActionPreference = 'Stop'
$taskAllowedKeys = @('DB_URL','DB_USERNAME','DB_PASSWORD','MYSQL_ROOT_PASSWORD','MYSQL_PORT','SERVER_PORT',
    'KEYCLOAK_PORT','KEYCLOAK_DB_USERNAME','KEYCLOAK_DB_PASSWORD','KEYCLOAK_ADMIN_USERNAME','KEYCLOAK_ADMIN_PASSWORD',
    'KEYCLOAK_ISSUER_URI','KEYCLOAK_JWKS_URI','AUTH_JWT_AUDIENCE','AUTH_JWT_CLOCK_SKEW',
    'KEYCLOAK_TOKEN_URI','KEYCLOAK_BROWSER_CLIENT_ID','AUTH_SESSION_REQUEST_TIMEOUT','AUTH_SESSION_COOKIE_SECURE',
    'KEYCLOAK_ADMIN_ENABLED','KEYCLOAK_ADMIN_SERVER_URL','KEYCLOAK_ADMIN_REALM','KEYCLOAK_ADMIN_CONNECT_TIMEOUT','KEYCLOAK_ADMIN_REQUEST_TIMEOUT',
    'AUTH_CORS_ORIGINS','AUTH_CORS_MAX_AGE','AUTH_BOOTSTRAP_ENABLED','AUTH_BOOTSTRAP_USERNAME','AUTH_BOOTSTRAP_FULL_NAME','AUTH_BOOTSTRAP_IDENTITY_ID',
    'OPENAPI_ENABLED','NOTIFICATION_WORKER_ENABLED','NOTIFICATION_REMINDERS_ENABLED','NOTIFICATION_BATCH_SIZE',
    'NOTIFICATION_MAX_ATTEMPTS','NOTIFICATION_LEASE','NOTIFICATION_RETRY_DELAY','GARAGE_TIME_ZONE',
    'NOTIFICATION_REMINDER_DAYS','NOTIFICATION_EMAIL_ENABLED','NOTIFICATION_EMAIL_FROM',
    'SMTP_HOST','SMTP_PORT','SMTP_USERNAME','SMTP_PASSWORD','SMTP_AUTH','SMTP_STARTTLS',
    'NOTIFICATION_SMS_ENABLED','SMS_GATEWAY_URL','SMS_GATEWAY_TOKEN',
    'AUTH_PASSWORD_MIN_LENGTH','PAGINATION_DEFAULT_SIZE','PAGINATION_MAX_SIZE','PAGINATION_MAX_PAGE','REPORT_MAX_PERIOD','NOTIFICATION_CONNECT_TIMEOUT','NOTIFICATION_REQUEST_TIMEOUT','NOTIFICATION_POLL_DELAY','NOTIFICATION_REMINDER_CRON','NOTIFICATION_REMINDER_MAX_BATCHES','NOTIFICATION_DEFAULT_SUBJECT','SMTP_CONNECT_TIMEOUT_MS','SMTP_READ_TIMEOUT_MS','SMTP_WRITE_TIMEOUT_MS','WORKSHOP_DEFAULT_SERVICE_MINUTES','WORKSHOP_RESERVATION_HOLD','WORKSHOP_MAX_ATTACHMENT_BYTES','WORKSHOP_MAX_UPLOAD_REQUEST_BYTES')
foreach ($taskLine in Get-Content -LiteralPath $Path) {
    if ([string]::IsNullOrWhiteSpace($taskLine) -or $taskLine.TrimStart().StartsWith('#')) { continue }
    $taskPair = $taskLine.Split(@('='), 2, [StringSplitOptions]::None)
    if ($taskPair.Count -ne 2 -or $taskAllowedKeys -notcontains $taskPair[0].Trim()) { throw 'Unsupported entry in local environment file' }
    [Environment]::SetEnvironmentVariable($taskPair[0].Trim(), $taskPair[1], 'Process')
}
Write-Output 'Loaded local configuration into this PowerShell process; secrets were not printed.'
